local _, ns = ...
local UII = ns.UII

-- Fojji's profiles, copied from Wago on 2026-10-26. To update, replace a string
-- with the newer one from its Wago page.

-- https://wago.io/Fojji-ElvUI  ("Fojji - ElvUI Standard", version 2.0.5-50)
local ELVUI_STANDARD = "!E2!"

-- https://wago.io/Fojji-ElvUI-Healer  ("Fojji - ElvUI Healer", version 2.0.5-46)
local ELVUI_HEALER = "!E2!"

-- https://wago.io/Fojji-Plater  ("Fojji - Plater Profile", version 1.0.9), used by both packs
local PLATER = "!PLATER:2!"

local function FojjiPack(name, elvui)
	return {
		name = name,
		author = "Fojji",
		requires = {
			{ addon = "FojjiCore", why = "fonts and textures" },
		},
		addons = {
			ElvUI = { strings = { elvui } },
			Plater = { strings = { PLATER } },
		},
	}
end

UII:RegisterPack(FojjiPack("Fojji DPS / Tank", ELVUI_STANDARD))
UII:RegisterPack(FojjiPack("Fojji Healer", ELVUI_HEALER))
